public static <T> int writeDelimitedTo(OutputStream outputStream, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        int size = schema.getSerializedSize(message);
        if (size <= 0) {
            return 0;
        }
        LinkedBuffer startBuf = buffer.head.next;
        if (startBuf == null) {
            startBuf = buffer.head = new LinkedBuffer(size);
        } else {
            startBuf = buffer.head.add(size);
        }
        ByteWriter writer = startBuf.writer;
        writer.len = 0;
        writer.writeVarint64(size);
        schema.writeTo(writer.getCodedOutput(), message);
        writer.flush();
        outputStream.write(startBuf.getBuf(), 0, startBuf.bufferSize);
        return size;
    }

