    // Write the length of the message and the actual message to the output stream
    final int lengthSize = 4;
    final int messageDataSize = messageSize - lengthSize;
    final int totalSize = messageDataSize + lengthSize;
    out.writeInt(totalSize);
    out.write(buffer.getData(), lengthSize, messageDataSize);

