public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Class<?>[] typeArguments = parameterizedType.getActualTypeArguments();
    Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType);
    if (typeVariableMap == null) {
        return null;
    }
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type argument = typeArguments[i];
        if (argument instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) argument;
            Type mappedType = typeVariableMap.get(typeVariable);
            if (mappedType != null) {
                resolvedArguments[i] = (Class<?>) mappedType;
            } else {
                return null;
            }
        } else {
            resolvedArguments[i] = (Class<?>) argument;
        }
    }
    return resolvedArguments;
}

private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    for (TypeVariable<?> typeVariable : targetType.getTypeParameters()) {
        Type[] bounds = typeVariable.getBounds();
        for (Type bound : bounds) {
            if (bound instanceof Class<?>) {
                typeVariableMap.put(typeVariable, bound);
            }
        }
    }
    return typeVariableMap;
}

