            timeRanges.add(timeRange);
            currentStartTime = currentEndTime;
            currentEndTime = currentStartTime + FETCH_DATA_DURATION;
        }
        // Add the last time range if needed
        if (currentStartTime < endTime) {
            TimeRange timeRange = new TimeRange(currentStartTime, endTime);
            timeRanges.add(timeRange);
        }
        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start,long end) {
    long diff = end - start;
    List<TimeRange> ranges = new ArrayList<>();
    while (diff > 0) {
        long endTime = start + FETCH_DATA_DURATION;
        if (endTime > end) {
            endTime = end;
        }
        ranges.add(new TimeRange(start, endTime));
        start = endTime;
        diff -= FETCH_DATA_DURATION;
    }
    return ranges;
}

