  if (str == null || suffix == null) {
    return true;
  }
  int strLength = str.length();
  int suffixLength = suffix.length();
  int strEnd = strLength - suffixLength - 1;
  if (strEnd < 0) {
    return false;
  }
  if (ignoreCase) {
    return strLength >= suffixLength && str.substring(strEnd).equalsIgnoreCase(suffix);
  } else {
    return strLength >= suffixLength && str.substring(strEnd).equals(suffix);
