    int len = str.length();
    StringBuilder builder = new StringBuilder(len);
    int pos;
    for (pos = 0; pos < len; pos++) {
        char c = str.charAt(pos);
        if (c == '\\') {
            if (pos + 1 < len) {
                char nextChar = str.charAt(pos + 1);
                if (nextChar == 't') {
                    builder.append('\t');
                    pos++;
                } else if (nextChar == 'n') {
                    builder.append('\n');
                    pos++;
                } else if (nextChar == 'r') {
                    builder.append('\r');
                    pos++;
                } else if (nextChar == 'f') {
                    builder.append('\f');
                    pos++;
                } else if (nextChar == 'u') {
                    builder.append(readUnicodeEscape(str, pos));
                    pos++;
                } else if (nextChar == '\\') {
                    builder.append('\\');
                    pos++;
                } else {
                    builder.append(c);
                }
            } else {
                builder.append(c);
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

