void removeUnusedNodes() {
    // Iterate through all nodes in the Category tree
    Iterator<Node> iter = getRootNode().iterator();
    while (iter.hasNext()) {
        Node node = iter.next();
        // Check if the node is inactive and has no children
        if (!isActiveNode(node) && node.getChildCount() == 0) {
            // Remove the node from the tree
            node.removeFromParent();
            // Decrement the count of inactive nodes
            inactiveNodes--;
        }
    }
    // Return the number of inactive nodes removed
    return inactiveNodes;
}

protected boolean isActiveNode(Node node) {
    // Check if the node has been used in any of the graphs
    if (usedNodeList.contains(node)) {
        return true;
    }
    // Check if the node has any active children
    for (Node child : node.children()) {
        if (isActiveNode(child)) {
            return true;
        }
    }
    return false;
}

