public void fill() throws IOException {
    if (bytecount >= length) {
        throw new IOException("No more data available");
    } else {
        buffer.flip();
        buffer = channel.read(buffer);
        bytecount += buffer.remaining();
        buffer.rewind();
    }
}

public byte readByte() throws IOException {
    if (bufferPointer < bufferEnd) {
        return buffer[bufferPointer++];
    }
    refillBuffer();
    return buffer[bufferPointer++];
}

private void refillBuffer() throws IOException {
    bufferPointer = 0;
    bufferEnd = inputStream.read(buffer);
    if (bufferEnd < 0) {
        throw new EOFException();
    }
}

public byte readByte() throws IOException {
    if (buffer.length() == 0) {
        refillBuffer();
    }
    byte value = buffer.charAt(0);
    buffer.deleteCharAt(0);
    return value;
}

private void refillBuffer() throws IOException {
    int numBytesToRead = Math.min(16, input.available());
    if (numBytesToRead == 0) {
        throw new IOException("No more data available");
    }
    char[] bytes = new char[numBytesToRead];
    int numBytesRead = input.read(bytes);
    buffer.append(new String(bytes, 0, numBytesRead));
}

void readByte() throws IOException {
    if (buffer.isEmpty()) {
        refillBuffer();
    }
    return buffer.removeFirst().byteValue();
}

public byte readByte() throws IOException {
    if (bufferIndex >= buffer.length) {
        fillBuffer();
    }
    return buffer[bufferIndex++];
}

private void fillBuffer() throws IOException {
    if (bufferIndex >= buffer.length) {
        throw new IOException("Buffer overflow");
    }
    int numBytesRead = in.read(buffer);
    bufferIndex = 0;
    if (numBytesRead < 0) {
        throw new IOException("End of input stream");
    }
}

