private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if(str == null || prefix == null){
        return (str == null) && (prefix == null);
    }
    int strStart = 0;
    int prefixStart = 0;
    int index = 0;

    while(true){
        boolean match = true;
        if(ignoreCase){
            match = str.charAt(strStart + index) == prefix.toUpperCase().charAt(prefixStart + index);
        }
        else{
            match = str.charAt(strStart + index) == prefix.charAt(prefixStart + index);
        }

        if(!match || (str.length() == index) || (prefix.length() == index)){
            return match;
        }

        index++;
    }
}

