	if ( str == null || prefix == null ) {
		return false;
	}
	int strLen = str.length();
	int prefixLen = prefix.length();
	if ( prefixLen > strLen ) {
		return false;
	}
	for ( int i = 0; i < prefixLen; i++ ) {
		char strCh = str.charAt(i);
		char prefixCh = prefix.charAt(i);
		if ( strCh != prefixCh ) {
			if ( ignoreCase ) {
				strCh = Character.toLowerCase(strCh);
				prefixCh = Character.toLowerCase(prefixCh);
				if ( strCh != prefixCh ) {
					return false;
				}
			} else {
				return false;
			}
		}
	}
	return true;
}

