private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<List<Pair<Integer,Integer>>,E>> localSeparatorList = computeLocalSeparatorList(edge);
        globalSeparatorList.addAll(localSeparatorList);
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeLocalSeparatorList(E edge) {
    List<Pair<List<Pair<Integer,Integer>>,E>> localSeparatorList = new ArrayList<>();
    for (V vertex : graph.getNeighbors(edge)) {
        List<Pair<List<Pair<Integer,Integer>>,E>> neighborSeparatorList = computeNeighborSeparatorList(vertex);
        localSeparatorList.addAll(neighborSeparatorList);
    }
    return localSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeNeighborSeparatorList(V vertex) {
    List<Pair<List<Pair<Integer,Integer>>,E>> neighborSeparatorList = new ArrayList<>();
    for (E neighborEdge : graph.getEdges(vertex)) {
        if (graph.getEndpoints(neighborEdge).contains(vertex)) {
            List<Pair<Integer,Integer>> separator = computeSeparator(neighborEdge);
            neighborSeparatorList.add(new Pair<>(separator, neighborEdge));
        }
    }
    return neighborSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {

List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

for (E e : graph.getEdges()) {
    List<Pair<Integer,Integer>> localSeparatorList = computeLocalSeparatorList(e);
    globalSeparatorList.add(new Pair<>(localSeparatorList, e));
}

return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeLocalSeparatorList(E e) {

List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

List<Integer> neighborVertices = graph.getNeighborsOf(e.getFirst());
neighborVertices.addAll(graph.getNeighborsOf(e.getSecond()));

for (Integer v : neighborVertices) {
    List<Integer> clique = new ArrayList<>();
    boolean cliqueFound = false;

    for (int i = 0; i < v.size(); i++) {
        if (graph.containsEdge(v.get(i), v.get(i + 1))) {
            clique.add(v.get(i));
        } else if (i > 0) {
            localSeparatorList.add(new Pair<>(clique, e));
            cliqueFound = true;
            break;
        }
    }

    if (!cliqueFound) {
        localSeparatorList.add(new Pair<>(clique, e));
    }
}

return localSeparatorList;
}

public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Pair<Integer, Integer>> vertexList = new ArrayList<>();
        for (DefaultWeightedEdge edge : graph.edgesOf(e.either())) {
            vertexList.add(new Pair<>(e.either().id(), e.opposite(e.either()).id()));
        }
        separatorList.add(new Pair<>(vertexList, e));
    }
    return separatorList;
}

List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> separators = computeSeparators(edge);
        separatorList.add(new Pair(separators, edge));
    }
    return separatorList;
}

private List<Pair<Integer, Integer>> computeSeparators(E edge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (int i = 0; i < graph.getDegree(edge.getFirst()); i++) {
        Pair<Integer, Integer> separator = computeSeparator(edge.getFirst(), i);
        if (separator != null) {
            separators.add(separator);
        }
    }
    for (int i = 0; i < graph.getDegree(edge.getSecond()); i++) {
        Pair<Integer, Integer> separator = computeSeparator(edge.getSecond(), i);
        if (separator != null) {
            separators.add(separator);
        }
    }
    return separators;
}

private Pair<Integer, Integer> computeSeparator(int vertex, int index) {
    E edge = graph.getEdge(vertex, index);
    if (edge != null) {
        return new Pair(vertex, edge.getFirst());
    }
    return null;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        for (V source : graph.edges(edge)) {
            separators.addAll(getSeparators(edge, source));
        }
        separatorList.add(new Pair<>(separators, edge));
    }
    return separatorList;
}

