private void abbreviate(int nameStart, StringBuffer buf) {
	if (nameStart == null || buf == null) {
		throw new IllegalArgumentException("Both nameStart and buf cannot be null.");
	}
	StringBuffer name = new StringBuffer();
	for (int i = nameStart; i < name.length(); i++) {
		if (name.charAt(i) == '.') {
			break;
		}
		name.append(name.charAt(i));
	}
	if (name.length() > 5) {
		StringBuffer abbreviation = new StringBuffer();
		for (int i = 0; i < name.length(); i++) {
			if (Character.isUpperCase(name.charAt(i))) {
				abbreviation.append(name.charAt(i));
				break;
			}
		}
		for (int i = 0; i < abbreviation.length(); i++) {
			buf.append(abbreviation.charAt(i));
		}
	} else {
		buf.append(name);
	}
}

