    AbstractType frameElement = outputFrameStack.pop();
    if (!frameElement.getDescriptor().equals(descriptor)) {
      throw new VerifyError("Unexpected type popped from output frame stack: " + frameElement.getDescriptor() + " !=  " + descriptor);
    }
  }
}

