void pop(String descriptor){
 int count = 0, stackSize = outputStack.size();
 boolean desiredArgTypeFound = false;
 for(int i = 0; i < stackSize; i++){
   AbstractType type = outputStack.get(i);
   if (type.getDescriptor().equals(descriptor)){
     count++;
     outputStack.remove(i);
     i--;
     stackSize--;
     if (count == type.numArgs){
       desiredArgTypeFound = true;
       break;
     }
   }
 }
 if (!desiredArgTypeFound) {
   throw new RuntimeException("Could not find type matching given type")
 }
}

