public static String encodeTemplateNames(String s) {
    Pattern p = Pattern.compile("\\{.*?\\}");
    Matcher m = p.matcher(s);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        String replacement = URLEncoder.encode(m.group(), StandardCharsets.UTF_8.name());
        m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
    }
    m.appendTail(sb);
    return sb.toString();
}

public static String encodeTemplateNames(String s) {
    String encodedString = s;

    // Replace all occurrences of '{' and '}' with their percent-encoded values
    encodedString = encodedString.replace("{", "%7B").replace("}", "%7D");

    return encodedString;
}

