public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Check if the relative path is empty
    if (relativePath.isEmpty()) {
        return path;
    }

    // Split the relative path into its individual components
    String[] relativeComponents = relativePath.split("/");

    // Split the path into its individual components
    String[] pathComponents = path.split("/");

    // Iterate through the relative path components
    for (String relativeComponent : relativeComponents) {
        // Check if the relative component is "." or ".."
        if (relativeComponent.equals(".") || relativeComponent.equals("..")) {
            // If it is "..", remove the last component of the path
            if (relativeComponent.equals("..")) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        // If it is not "." or "..", add it to the path
        } else {
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = relativeComponent;
        }
    }

    // Join the path components back into a string
    return String.join("/", pathComponents);
}

