public static int indexOfExtension (String filename) {
    int lastSeparatorIndex = indexOfLastSeparator(filename);
    if (lastSeparatorIndex == -1) {
        return -1;
    }
    int extensionIndex = filename.lastIndexOf('.');
    if (extensionIndex > lastSeparatorIndex) {
        return -1;
    } else {
        return extensionIndex;
    }
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastUnix = indexOfLastSeparator(filename);
    int lastWindows = filename.lastIndexOf(".");
    if (lastUnix == -1 && lastWindows == -1) {
        return -1;
    } else if (lastUnix == -1) {
        return lastWindows;
    } else if (lastWindows == -1) {
        return lastUnix;
    } else {
        return Math.max(lastUnix, lastWindows);
    }
}

public int indexOfExtension(String filename){
	// Check if the filename is null or empty
	if (filename == null || filename.isEmpty()) {
		return -1;
	}

	// Get the index of the last dot in the filename
	int index = filename.lastIndexOf(".");

	// Check if the dot is preceded by a directory separator
	if (index > 0 && filename.charAt(index - 1) == "/") {
		// Return the index of the last dot
		return index;
	} else {
		// Return -1 if the dot is not preceded by a directory separator
		return -1;
	}
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator == -1) {
        return -1;
    } else {
        return nextIndexOf(filename, lastSeparator, '.');
    }
}

private static int indexOfLastSeparator(String filename) {
    // handle Unix format
    int lastSeparatorUnix = filename.lastIndexOf('/');
    // handle Windows format
    int lastSeparatorWindows = filename.lastIndexOf('\\');
    // return the latest index
    return Math.max(lastSeparatorUnix, lastSeparatorWindows);
}

private static int nextIndexOf(String filename, int startIndex, char ch) {
    return filename.indexOf(ch, startIndex + 1);
}

