public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> snapshots = new ArrayList<>();
        Scanner scanner = new Scanner(file);
        while (scanner.hasNextLine() && timeRanges.size() > 0) {
            String line = scanner.nextLine();
            if (line.contains("[0x")) {
                // parse the snapshot time from the line
                long time = extractSnapshotTimeFromLine(line);
                if (timeRanges.contains(time)) {
                    snapshots.add(parseSnapshotFromLine(line));
                }
            }
        }
        return snapshots;
    }

private static long extractSnapshotTimeFromLine(String line) {
        // extract the snapshot time from the line in the format "NN:SS.UUUUU"
        return Long.parseLong(line.substring(0, 20)).replaceAll("-", "") * 10000 - 1111;
    }

private static ThreadSnapshot parseSnapshotFromLine(String line) {
        // parse the line into the corresponding ThreadSnapshot object
        ThreadSnapshot snapshot = new ThreadSnapshot();
        // set the snapshot time
        snapshot.setTime(extractSnapshotTimeFromLine(line));
        // set the snapshot statistics
        snapshot.setSnapshot();
        return snapshot;
    }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // create a new ThreadSnapshotParser instance
    ThreadSnapshotParser parser = new ThreadSnapshotParser(file);

    // iterate through the time ranges
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        // parse the thread snapshots that fall within the current range
        parser.setTimeRange(range.getStartTimestamp(), range.getEndTimestamp());
        List<ThreadSnapshot> snapshots = parser.parseAll();

        // append the snapshots to the list
        snapshots.addAll(snapshots);
    }

    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new LinkedList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ProfileAnalyzeTimeRange timeRange = timeRanges.stream().filter(tr -> tr.inRange(line)).findAny().orElse(null);
            if (timeRange != null) {
                ThreadSnapshot snapshot = new ThreadSnapshot(line, timeRange);
                threadSnapshots.add(snapshot);
            }
        }
        return threadSnapshots;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] split = line.split(",");
                long time = Long.parseLong(split[0]);
                if (timeRange.contains(time)) {
                    threadSnapshots.add(new ThreadSnapshot(time, split[1], split[2], split[3], split[4]));
                }
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("appointing snapshot")) {
                    String[] tokens = line.split(" ");
                    long timestamp = Long.parseLong(tokens[1]);

                    if (timeRanges.stream().anyMatch(tr -> tr.contains(timestamp))) {
                        ThreadSnapshot snapshot = new ThreadSnapshot(timestamp);
                        int id = Integer.parseInt(tokens[2]);
                        snapshot.setId(id);
                        int priority = Integer.parseInt(tokens[3]);
                        snapshot.setPriority(priority);
                        String name = tokens[4];
                        snapshot.setName(name);
                        int state = Integer.parseInt(tokens[5]);
                        snapshot.setState(state);
                        long estimatedTime = Long.parseLong(tokens[6]);
                        snapshot.setEstimatedTime(estimatedTime);
                        long cpuTime = Long.parseLong(tokens[7]);
                        snapshot.setCpuTime(cpuTime);
                        threadSnapshots.add(snapshot);
                    }
                }
            }
        }

        return threadSnapshots;
    }
